QUESTIONS = [{'id': 1, 'topic': 'Foundations and Applications of AI', 'type': 'mcq', 'difficulty': 'Easy', 'question': 'A hospital uses software to predict which patients may need urgent attention based on symptoms and test results. Which description best fits this system?', 'options': ['A rule-free calculator', 'An AI decision-support system', 'A file compression utility', 'A simple text editor'], 'answer': 'An AI decision-support system', 'explanation': 'The system uses patient data to infer risk and support decisions, which is a common AI application.', 'hint': 'Think about software that uses data to support decisions.'}, {'id': 2, 'topic': 'Foundations and Applications of AI', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A supermarket analyses purchase histories to recommend products to each customer. Which AI application is most directly involved?', 'options': ['Recommendation system', 'Depth-first search', 'Compiler design', 'Manual sorting'], 'answer': 'Recommendation system', 'explanation': 'Recommendation systems use patterns in user behaviour and item data to suggest relevant products.', 'hint': 'Streaming services and online shops use this feature.'}, {'id': 3, 'topic': 'Foundations and Applications of AI', 'type': 'mcq', 'difficulty': 'Easy', 'question': 'Which task is the clearest example of natural language processing (NLP)?', 'options': ['Detecting a cracked road from a photograph', 'Translating a customer review into another language', "Measuring a machine's temperature", 'Sorting files by size'], 'answer': 'Translating a customer review into another language', 'explanation': 'NLP enables computers to process, interpret, and generate human language.', 'hint': 'Look for a task involving human language.'}, {'id': 4, 'topic': 'Foundations and Applications of AI', 'type': 'tf', 'difficulty': 'Easy', 'question': 'Every program that follows fixed instructions is necessarily an intelligent agent.', 'options': ['True', 'False'], 'answer': 'False', 'explanation': 'A fixed program may simply execute instructions. An intelligent agent perceives an environment and selects actions to pursue goals or improve performance.', 'hint': 'An agent must do more than execute a fixed sequence.'}, {'id': 5, 'topic': 'Foundations and Applications of AI', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A camera system identifies pedestrians, traffic signs, and lanes from road images. Which AI area is central to this task?', 'options': ['Computer vision', 'Constraint satisfaction', 'Database normalization', 'Depth-first search'], 'answer': 'Computer vision', 'explanation': 'Computer vision extracts useful information from images and video.', 'hint': 'The input is visual data.'}, {'id': 6, 'topic': 'Turing Test', 'type': 'mcq', 'difficulty': 'Easy', 'question': 'In the classic Turing Test setup, what is the judge primarily trying to determine?', 'options': ['Whether a machine can run faster than a human', "Whether a machine's conversational responses can be distinguished from a human's", 'Whether a machine has a physical body', 'Whether a machine can store unlimited data'], 'answer': "Whether a machine's conversational responses can be distinguished from a human's", 'explanation': 'The test evaluates whether a machine can converse in a way that is indistinguishable from a human to an evaluator.', 'hint': 'It is a test based on conversation, not physical appearance.'}, {'id': 7, 'topic': 'Turing Test', 'type': 'tf', 'difficulty': 'Medium', 'question': 'Passing a Turing Test proves that a machine has consciousness.', 'options': ['True', 'False'], 'answer': 'False', 'explanation': 'The test concerns observable conversational behaviour; it does not establish consciousness or subjective experience.', 'hint': 'Consider what the test can observe versus what it cannot establish.'}, {'id': 8, 'topic': 'Rational Agents', 'type': 'mcq', 'difficulty': 'Easy', 'question': 'A rational agent selects an action that is expected to:', 'options': ['Maximize the number of actions taken', 'Best achieve its performance measure given available information', 'Always copy the previous action', 'Guarantee perfect results in every situation'], 'answer': 'Best achieve its performance measure given available information', 'explanation': 'Rationality depends on percepts, available actions, knowledge, and the performance measure—not on guaranteed perfection.', 'hint': 'Rational means choosing the best expected action under the available information.'}, {'id': 9, 'topic': 'Rational Agents', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A robot vacuum detects a large spill and chooses to clean that area before returning to its charging dock. What makes this behaviour rational?', 'options': ['It chooses an action that better serves its cleaning objective in the current situation', 'It always moves to the left', 'It ignores sensor readings', 'It selects actions randomly'], 'answer': 'It chooses an action that better serves its cleaning objective in the current situation', 'explanation': 'The robot uses current percepts and its objective to choose a useful action.', 'hint': "Relate the action to the agent's performance goal."}, {'id': 10, 'topic': 'Intelligent Agents', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'Which sequence best represents an agent interacting with its environment?', 'options': ['Actuators → percepts → sensors', 'Percepts from sensors → agent decision → action through actuators', 'Database → compiler → monitor only', 'Action → no feedback → fixed outcome'], 'answer': 'Percepts from sensors → agent decision → action through actuators', 'explanation': 'Sensors gather percepts; the agent selects an action; actuators carry out the action.', 'hint': 'Sensors perceive; actuators act.'}, {'id': 11, 'topic': 'Agents and Environments', 'type': 'match', 'difficulty': 'Medium', 'question': 'Match each agent component to its role. Choose the option with all pairings correct: Sensor, Actuator, Performance measure.', 'options': ['Sensor—perceives; Actuator—acts; Performance measure—evaluates success', 'Sensor—acts; Actuator—stores goals; Performance measure—perceives', 'Sensor—evaluates success; Actuator—perceives; Performance measure—acts', 'Sensor—stores all knowledge; Actuator—judges success; Performance measure—moves'], 'answer': 'Sensor—perceives; Actuator—acts; Performance measure—evaluates success', 'explanation': 'Sensors receive information, actuators affect the environment, and the performance measure defines how success is assessed.', 'hint': 'Think input, output, and evaluation.'}, {'id': 12, 'topic': 'Nature of Environments', 'type': 'mcq', 'difficulty': 'Medium', 'question': "A chess agent can see the complete board and all pieces, but cannot know the opponent's future move. The environment is best described as:", 'options': ['Fully observable and deterministic for the current state transition', 'Partially observable because pieces are hidden', 'Continuous because the board has squares', 'Unknown because rules do not exist'], 'answer': 'Fully observable and deterministic for the current state transition', 'explanation': "The board state is fully visible. Chess moves have rule-governed outcomes, although the opponent's future choice is uncertain.", 'hint': "Distinguish visibility of the current state from uncertainty about another agent's choice."}, {'id': 13, 'topic': 'Nature of Environments', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A self-driving car operates in traffic where other drivers may behave unpredictably. Which environment property is most relevant?', 'options': ['Strategic and dynamic', 'Static and single-agent', 'Fully predictable in every detail', 'Episodic with no state changes'], 'answer': 'Strategic and dynamic', 'explanation': 'Other drivers are agents whose choices affect outcomes, and the road situation changes while the car operates.', 'hint': 'Other decision-makers and changing conditions matter.'}, {'id': 14, 'topic': 'Nature of Environments', 'type': 'tf', 'difficulty': 'Easy', 'question': 'In a static environment, the environment does not change while the agent is deliberating.', 'options': ['True', 'False'], 'answer': 'True', 'explanation': "A static environment remains unchanged during the agent's decision process; a dynamic one can change.", 'hint': 'Static is the opposite of changing during deliberation.'}, {'id': 15, 'topic': 'Nature of Environments', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A medical diagnosis system receives incomplete symptoms and uncertain test results. The environment is likely:', 'options': ['Partially observable and stochastic', 'Fully observable and deterministic', 'Static and fully known in every respect', 'A simple linear list'], 'answer': 'Partially observable and stochastic', 'explanation': 'The system cannot directly observe the complete health state, and outcomes may be uncertain.', 'hint': 'The true state is not fully visible, and outcomes can be uncertain.'}, {'id': 16, 'topic': 'Good Behaviour', 'type': 'assertion', 'difficulty': 'Medium', 'question': 'Assertion: A rational agent may choose an action that later turns out badly. Reason: Rationality is judged using the information and actions available when the choice is made.', 'options': ['Both Assertion and Reason are true, and Reason explains Assertion', 'Both are true, but Reason does not explain Assertion', 'Assertion is true, Reason is false', 'Assertion is false, Reason is true'], 'answer': 'Both Assertion and Reason are true, and Reason explains Assertion', 'explanation': 'Rationality is about expected performance given available information, not hindsight or guaranteed success.', 'hint': 'A good decision can still have an unlucky outcome.'}, {'id': 17, 'topic': 'Good Behaviour', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A delivery robot is evaluated on safety, delivery time, and avoiding restricted areas. What should guide its action selection?', 'options': ['The defined performance measure and current percepts', 'Only the shortest route, regardless of safety', 'The most visually interesting route', 'A random choice at each junction'], 'answer': 'The defined performance measure and current percepts', 'explanation': 'A rational agent should balance the stated objectives using what it currently knows.', 'hint': 'The performance measure defines what counts as success.'}, {'id': 18, 'topic': 'Problems and Problem Spaces', 'type': 'mcq', 'difficulty': 'Easy', 'question': 'In a search problem, what does the initial state represent?', 'options': ['The state where the search begins', 'The final answer in every problem', 'The cost of all actions combined', 'The list of heuristic values only'], 'answer': 'The state where the search begins', 'explanation': 'The initial state is the starting configuration from which search explores possible states.', 'hint': 'It is the starting point.'}, {'id': 19, 'topic': 'Problems and Problem Spaces', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'Which set of elements most completely defines a classical search problem?', 'options': ['Initial state, actions/successor function, goal test, and path cost', 'Only the goal state', 'Only the programming language', 'Only a heuristic estimate'], 'answer': 'Initial state, actions/successor function, goal test, and path cost', 'explanation': 'These components specify where search starts, how states change, what counts as a solution, and how solution paths are evaluated.', 'hint': 'Include start, transitions, goal, and cost.'}, {'id': 20, 'topic': 'Problems and Problem Spaces', 'type': 'fill', 'difficulty': 'Easy', 'question': 'The set of states reachable from the initial state by applying legal actions is called the state ________.', 'options': [], 'answer': 'space', 'explanation': "The state space is the collection of states considered or reachable under the problem's actions.", 'hint': 'The term is commonly written as two words: state space.', 'accepted_answers': ['space']}, {'id': 21, 'topic': 'State Space Search', 'type': 'search', 'difficulty': 'Medium', 'question': 'A map is represented as a graph. BFS explores neighbours in increasing number of edges from the start. If every edge has equal cost, what does BFS find?', 'options': ['A path with the fewest edges', 'Always the path with the lowest heuristic', 'Always the deepest solution', 'A path chosen by alphabetical order only'], 'answer': 'A path with the fewest edges', 'explanation': 'BFS finds a shallowest solution; when all edges have equal cost, this is also a minimum-cost path.', 'hint': 'BFS explores level by level.'}, {'id': 22, 'topic': 'State Space Search', 'type': 'search', 'difficulty': 'Medium', 'question': 'A maze solver uses DFS and follows one branch deeply before backtracking. What is a key limitation of DFS?', 'options': ['It is not generally guaranteed to find the shortest path', 'It can never use a stack', 'It always explores every node at once', 'It requires a heuristic for every state'], 'answer': 'It is not generally guaranteed to find the shortest path', 'explanation': 'DFS can find a solution without finding the shallowest or least-cost solution; it can also get stuck in infinite-depth paths without safeguards.', 'hint': 'Think about whether DFS compares all shorter alternatives first.'}, {'id': 23, 'topic': 'State Space Search', 'type': 'search', 'difficulty': 'Easy', 'question': 'Which data structure is typically used by breadth-first search to manage the frontier?', 'options': ['Queue', 'Stack', 'Only a priority queue ordered by heuristic', 'Hash table alone'], 'answer': 'Queue', 'explanation': 'A FIFO queue makes BFS expand states in the order they were discovered.', 'hint': 'First in, first out.'}, {'id': 24, 'topic': 'State Space Search', 'type': 'search', 'difficulty': 'Easy', 'question': 'Which data structure most naturally supports depth-first search?', 'options': ['Stack', 'Queue', 'Sorted spreadsheet', 'Circular buffer only'], 'answer': 'Stack', 'explanation': 'A LIFO stack supports exploring the most recently discovered state first; recursion can also implement this behaviour.', 'hint': 'Last in, first out.'}, {'id': 25, 'topic': 'Production Systems', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A production system contains IF–THEN rules, a working memory of facts, and a rule-selection mechanism. What does the inference/control mechanism do?', 'options': ['Chooses applicable rules and coordinates their execution', 'Physically senses the environment', 'Stores only images', 'Guarantees every rule fires simultaneously'], 'answer': 'Chooses applicable rules and coordinates their execution', 'explanation': 'The control strategy selects which applicable production rule to apply and manages the rule-firing process.', 'hint': 'Rules are available; something must decide which one fires.'}, {'id': 26, 'topic': 'Production Systems', 'type': 'tf', 'difficulty': 'Easy', 'question': 'A production rule is commonly represented as an IF condition THEN action/conclusion.', 'options': ['True', 'False'], 'answer': 'True', 'explanation': 'Production systems represent knowledge using condition–action rules.', 'hint': 'Recall the standard rule format.'}, {'id': 27, 'topic': 'Problem Characteristics', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A puzzle has a small number of states, clear legal moves, and a well-defined goal. It is best approached as:', 'options': ['A well-defined search problem', 'An unstructured task with no goal test', 'A task requiring no state representation', 'A purely random process'], 'answer': 'A well-defined search problem', 'explanation': 'The state, actions, and goal can be explicitly represented, making systematic search suitable.', 'hint': 'The rules and goal are clear.'}, {'id': 28, 'topic': 'Problem Characteristics', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'Why does a large branching factor make search difficult?', 'options': ['The number of generated states can grow rapidly with depth', 'It removes all possible solutions', 'It makes every heuristic exact', 'It guarantees BFS uses constant memory'], 'answer': 'The number of generated states can grow rapidly with depth', 'explanation': 'If each state has many successors, the search tree may grow exponentially as depth increases.', 'hint': 'Each level can multiply the number of candidates.'}, {'id': 29, 'topic': 'Issues in Search Program Design', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A graph search repeatedly revisits the same locations and runs for too long. Which design improvement is most directly useful?', 'options': ['Track explored states and avoid redundant expansion', 'Remove the goal test', 'Randomize all edge costs', 'Delete the initial state after one step'], 'answer': 'Track explored states and avoid redundant expansion', 'explanation': 'An explored set or suitable duplicate detection prevents unnecessary repeated work in graphs with cycles.', 'hint': 'The same state is being expanded more than once.'}, {'id': 30, 'topic': 'Issues in Search Program Design', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'Why should a search implementation store parent pointers or predecessor information?', 'options': ['To reconstruct the solution path after reaching a goal', 'To change the definition of the goal', 'To guarantee the heuristic is admissible', 'To avoid representing states'], 'answer': 'To reconstruct the solution path after reaching a goal', 'explanation': 'Parent links allow the algorithm to trace from a goal back to the initial state and return the actual sequence of actions.', 'hint': 'Finding the goal state is not the same as reporting the route.'}, {'id': 31, 'topic': 'Breadth-First Search', 'type': 'search', 'difficulty': 'Medium', 'question': 'In a graph, S connects to A and B; A connects to G; B connects to C. Neighbours are processed in the order shown. Which goal path will BFS find first?', 'options': ['S → A → G', 'S → B → C → G', 'S → B → C', 'S → A → B → G'], 'answer': 'S → A → G', 'explanation': 'BFS explores depth 1 before depth 2. Since A is processed before B and G is one step from A, S–A–G is found first.', 'hint': 'BFS explores the shallowest frontier first.'}, {'id': 32, 'topic': 'Depth-First Search', 'type': 'search', 'difficulty': 'Medium', 'question': 'DFS starts at S and visits A before B. A leads to dead end D, while B leads to goal G. What does a correct DFS do after exploring D with no new successors?', 'options': ["Backtracks to A's predecessor and continues with remaining alternatives", 'Stops and reports that no solution exists', 'Restarts at G without a path', 'Changes the goal test'], 'answer': "Backtracks to A's predecessor and continues with remaining alternatives", 'explanation': 'Backtracking allows DFS to explore other branches when the current branch cannot progress.', 'hint': 'DFS explores deeply, but it must return from dead ends.'}, {'id': 33, 'topic': 'Iterative Deepening', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'Why can iterative deepening search be useful when the solution depth is unknown?', 'options': ['It repeatedly runs depth-limited DFS with increasing limits', 'It stores every possible path in memory at once', 'It always uses a perfect heuristic', 'It expands only the deepest state once'], 'answer': 'It repeatedly runs depth-limited DFS with increasing limits', 'explanation': 'Iterative deepening combines low memory use with finding a shallowest solution when step costs are equal.', 'hint': 'The depth limit grows in stages: 0, 1, 2, and so on.'}, {'id': 34, 'topic': 'Hill Climbing', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A hill-climbing algorithm improves a schedule until every neighbouring schedule is worse, but a better schedule exists elsewhere. What has likely happened?', 'options': ['It reached a local optimum', 'It proved a global optimum', 'It performed BFS exhaustively', 'It found an admissible heuristic'], 'answer': 'It reached a local optimum', 'explanation': 'Hill climbing may stop at a state better than its neighbours even when a better state exists elsewhere in the search space.', 'hint': 'The best nearby state is not necessarily the best overall state.'}, {'id': 35, 'topic': 'Hill Climbing and Variations', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'Which variation is designed to reduce the risk of getting trapped at a local optimum by trying different starting points?', 'options': ['Random-restart hill climbing', 'Plain deterministic hill climbing from the same start only', 'Breadth-first search with no frontier', 'A fixed production rule'], 'answer': 'Random-restart hill climbing', 'explanation': 'Starting from different random states gives the algorithm multiple opportunities to reach a better region of the search space.', 'hint': 'The algorithm starts again from a different initial state.'}, {'id': 36, 'topic': 'Heuristic Search', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A heuristic h(n) is intended to estimate:', 'options': ['The remaining cost or distance from state n to a goal', 'The exact past cost for every path', 'The number of programming errors', 'The total number of sensors'], 'answer': 'The remaining cost or distance from state n to a goal', 'explanation': 'A heuristic guides informed search by estimating how far a state is from a goal.', 'hint': 'It estimates what remains, not what has already been spent.'}, {'id': 37, 'topic': 'Best-First Search', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'Greedy best-first search typically selects the frontier node with the:', 'options': ['Smallest heuristic estimate h(n)', 'Largest depth regardless of goal', 'Largest path cost g(n) only', 'Earliest alphabetical name only'], 'answer': 'Smallest heuristic estimate h(n)', 'explanation': 'Greedy best-first search prioritizes nodes that appear closest to the goal according to h(n).', 'hint': 'Greedy best-first uses the heuristic alone.'}, {'id': 38, 'topic': 'Heuristic Search', 'type': 'assertion', 'difficulty': 'Hard', 'question': 'Assertion: An admissible heuristic never overestimates the true remaining optimal cost. Reason: This property can help A* tree search find an optimal solution under the usual assumptions.', 'options': ['Both Assertion and Reason are true, and Reason explains Assertion', 'Both are true, but Reason does not explain Assertion', 'Assertion is true, Reason is false', 'Assertion is false, Reason is true'], 'answer': 'Both Assertion and Reason are true, and Reason explains Assertion', 'explanation': 'Admissibility provides a lower-bound estimate; with appropriate conditions, A* can return an optimal solution.', 'hint': 'Admissible means optimistic about remaining cost.'}, {'id': 39, 'topic': 'Constraint Satisfaction Problems', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A university timetable must assign courses to time slots so that courses sharing students do not overlap. What are the variables in this CSP?', 'options': ['The courses whose time slots must be assigned', 'Only the classroom walls', "The final timetable's font", "The search algorithm's source code"], 'answer': 'The courses whose time slots must be assigned', 'explanation': 'In a CSP, variables are the items to assign values to; here each course receives a time slot.', 'hint': 'Variables are the things that need values.'}, {'id': 40, 'topic': 'Constraint Satisfaction Problems', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'In a map-colouring CSP, neighbouring regions cannot have the same colour. What does this rule represent?', 'options': ['A constraint', 'A heuristic estimate only', 'An initial state only', 'A path cost necessarily'], 'answer': 'A constraint', 'explanation': 'The rule restricts which combinations of variable assignments are allowed.', 'hint': 'It specifies which assignments are permitted.'}, {'id': 41, 'topic': 'Means-End Analysis', 'type': 'mcq', 'difficulty': 'Medium', 'question': 'A robot needs to move a box to a target. It identifies the difference between the current state and goal, then chooses an action that reduces that difference. This is:', 'options': ['Means-end analysis', 'Random walk only', 'Pure breadth-first expansion', 'A Turing Test'], 'answer': 'Means-end analysis', 'explanation': 'Means-end analysis compares the current state with the goal and selects operators that reduce the difference, sometimes by creating subgoals.', 'hint': 'The method focuses on reducing the gap between current state and goal.'}, {'id': 42, 'topic': 'Means-End Analysis', 'type': 'tf', 'difficulty': 'Easy', 'question': 'Means-end analysis can create subgoals when an action cannot be applied until another condition is satisfied.', 'options': ['True', 'False'], 'answer': 'True', 'explanation': 'If an operator has unmet preconditions, satisfying them can become a subgoal.', 'hint': 'Subgoals help satisfy the conditions needed for a larger goal.'}, {'id': 43, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Medium', 'question': "A bank flags an unusual card purchase because it differs from a customer's normal spending pattern. Which application is this?", 'options': ['Fraud detection', 'Image segmentation', 'Iterative deepening', 'Map colouring'], 'answer': 'Fraud detection', 'explanation': 'Fraud detection systems identify transactions that appear anomalous or suspicious using patterns and risk indicators.', 'hint': 'The system is identifying suspicious financial activity.'}, {'id': 44, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A streaming platform suggests films based on what a viewer watched and rated. Which system is most relevant?', 'options': ['Recommendation system', 'Production system only with no data', 'Depth-limited search', 'A sensor actuator loop only'], 'answer': 'Recommendation system', 'explanation': 'The platform estimates what the viewer may like from viewing behaviour and similarities among users or items.', 'hint': 'It personalizes what appears next.'}, {'id': 45, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A phone assistant converts spoken instructions into text and then responds to a question. Which combination is most relevant?', 'options': ['Speech recognition and natural language processing', 'Only BFS and DFS', 'Only constraint propagation', 'Only database sorting'], 'answer': 'Speech recognition and natural language processing', 'explanation': 'Speech recognition converts audio to text; NLP interprets the language and helps generate a response.', 'hint': 'One part processes audio; another processes language.'}, {'id': 46, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A farm drone analyses crop images to locate areas showing possible disease. Which AI capability is central?', 'options': ['Computer vision', 'Means-end analysis alone', 'Turing Test', 'Queue management'], 'answer': 'Computer vision', 'explanation': 'Computer vision can detect visual patterns associated with crop stress or disease.', 'hint': 'The evidence comes from images.'}, {'id': 47, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A warehouse robot plans a route around shelves and avoids blocked aisles. Which AI concept is most directly involved?', 'options': ['State-space search and path planning', 'Natural language translation only', 'A conversational Turing Test', 'A static rule with no environment model'], 'answer': 'State-space search and path planning', 'explanation': 'The robot can represent locations as states and available movements as actions, then search for a feasible route.', 'hint': 'Locations and movements can be represented as states and transitions.'}, {'id': 48, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'An email service labels messages as spam by learning patterns from previously labelled emails. Which approach best describes this?', 'options': ['Machine learning-based classification', 'Manual route planning', 'Iterative deepening', 'A deterministic maze search'], 'answer': 'Machine learning-based classification', 'explanation': 'A classifier learns patterns from examples and predicts a label for new messages.', 'hint': 'The system learns from labelled examples.'}, {'id': 49, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Medium', 'question': 'A customer-service chatbot interprets a request and routes it to billing, delivery, or technical support. What is a key AI capability?', 'options': ['Intent classification using language understanding', 'Depth-first search through a physical maze', 'Hill climbing on a chessboard only', 'Constraint satisfaction without variables'], 'answer': 'Intent classification using language understanding', 'explanation': "The chatbot identifies the user's likely intent from their message and routes the request accordingly.", 'hint': 'It determines what the customer wants.'}, {'id': 50, 'topic': 'Real-World AI Applications', 'type': 'scenario', 'difficulty': 'Hard', 'question': 'A driver-assistance system detects a pedestrian and brakes. Which description best captures the agent loop?', 'options': ['Sensors perceive the scene, the system selects an action, and actuators apply braking', 'The actuator perceives and the sensor brakes', 'The system acts without any percepts', 'The system uses only a final score and no current state'], 'answer': 'Sensors perceive the scene, the system selects an action, and actuators apply braking', 'explanation': "The system senses its environment, processes percepts, selects an action, and acts through the vehicle's control mechanisms.", 'hint': 'Follow the perceive–decide–act sequence.'}]
